/**
 * CENTRAL COMMAND CORE — deterministic operational status.
 *
 * MOTION REFLECTS TRUTH. MOTION NEVER CREATES TRUTH.
 *
 * Every string here is chosen by runtime state. None is generated by a model,
 * and none claims execution, verification, a Guardian block or a progress
 * figure unless the snapshot actually carries that truth.
 *
 * Pure functions only — no clock, no timers, no fetches.
 */

/** Presence sizing intent from the approved design (compact, secondary). */
export const PRESENCE_SIZE_PX = 132;

/**
 * The status line under the presence. `null` means render nothing:
 * silence during capture is deliberate, not a missing case.
 *
 * @param {object} snapshot from buildCommandCoreSnapshot()
 * @returns {{text: string, tone: string, live: boolean}|null}
 */
export function operationalStatus(snapshot) {
  if (!snapshot || typeof snapshot !== "object") return null;
  const state = String(snapshot.coreState || "");

  const line = (text, tone = "info", live = true) => ({ text, tone, live });

  switch (state) {
    case "LISTENING":
      // No status noise while the user is actually speaking.
      return null;
    case "UNDERSTANDING":
      return line("Understanding request…");
    case "THINKING":
      return line("Working on your request…");
    case "DELEGATING":
      return line("Handing this to an agent…");
    case "SUPERVISING":
      return line(supervisingText(snapshot), "info");
    case "WAITING_APPROVAL":
      return line("Waiting for your approval.", "warn");
    case "EXECUTING":
      return line("Execution in progress.", "warn");
    case "VERIFYING":
      return line("Verifying the result…");
    case "BLOCKED":
      return line("Blocked by Trading Guardian.", "crit");
    case "SPEAKING":
      return line("Saathi is speaking.", "ok", false);
    case "DEGRADED":
      return line(degradedText(snapshot), "warn");
    case "IDLE":
    default:
      return snapshot.degraded ? line(degradedText(snapshot), "warn") : null;
  }
}

/**
 * SUPERVISING wording. A mission count is a real count. Progress is quoted only
 * when the server reported it; a heartbeat says "still running" and nothing more,
 * and UNKNOWN says nothing about how far along anything is.
 */
export function supervisingText(snapshot) {
  const ids = Array.isArray(snapshot?.activeMissionIds) ? snapshot.activeMissionIds : [];
  const liveness = Array.isArray(snapshot?.missionLiveness) ? snapshot.missionLiveness : [];
  const count = ids.length;
  const noun = count === 1 ? "agent is" : "agents are";
  const head = count > 0 ? `${count} ${noun} working.` : "An agent is working.";

  const reported = liveness.find((l) => l && l.kind === "PROGRESS" && typeof l.percent === "number");
  if (reported) return `${head} ${reported.percent}% reported.`;

  const beating = liveness.some((l) => l && l.kind === "HEARTBEAT");
  if (beating) return `${head} Still running.`;

  // UNKNOWN liveness must not become a progress claim of any kind.
  return head;
}

/** Factual system-health wording, naming only the sources that actually degraded. */
export function degradedText(snapshot) {
  const reasons = Array.isArray(snapshot?.degradedReasons) ? snapshot.degradedReasons : [];
  if (reasons.length === 0) return "Some capability is reduced.";
  const named = reasons
    .map((r) => ({ models: "model providers", gateway: "gateway", voice: "voice" }[r] || r))
    .join(" and ");
  return `Reduced capability: ${named}.`;
}

/**
 * Verification wording. Execution finishing is NOT verification passing.
 * Absence is reported as unavailable, never as success.
 */
export function verificationText(snapshot) {
  switch (String(snapshot?.verificationState || "")) {
    case "PASSED":
      return "Result verified.";
    case "FAILED":
      return "Verification failed.";
    case "EXECUTION_COMPLETE_VERIFICATION_UNAVAILABLE":
      return "Execution complete — verification unavailable.";
    default:
      return null;
  }
}

/**
 * Presence rendering contract. One grammar, driven by state, with orthogonal
 * conditions carried alongside rather than replacing the state.
 *
 * `energy` is passed through ONLY when a real measured value is supplied. There
 * is no synthesised waveform: absent a real signal, LISTENING renders from state
 * alone.
 */
export function presencePresentation(snapshot, options = {}) {
  const state = String(snapshot?.coreState || "IDLE");
  const reducedMotion = options.reducedMotion === true;
  const energy = typeof snapshot?.microphoneEnergy === "number" ? snapshot.microphoneEnergy : null;

  return {
    state,
    // Authority reads without motion, always.
    animate: !reducedMotion,
    degraded: snapshot?.degraded === true,
    supervising: snapshot?.supervising === true,
    // Only LISTENING consumes energy, and only when it is real.
    energy: state === "LISTENING" && !reducedMotion ? energy : null,
    label: presenceLabel(state),
    sizePx: PRESENCE_SIZE_PX,
  };
}

/** Accessible name for the presence. Never the only carrier of authority state. */
export function presenceLabel(state) {
  return {
    IDLE: "Saathi idle",
    LISTENING: "Saathi listening",
    UNDERSTANDING: "Saathi understanding your request",
    THINKING: "Saathi working on your request",
    SPEAKING: "Saathi speaking",
    DELEGATING: "Saathi handing work to an agent",
    SUPERVISING: "Saathi supervising a running agent",
    WAITING_APPROVAL: "Waiting for your approval",
    EXECUTING: "Execution in progress",
    VERIFYING: "Verifying the result",
    BLOCKED: "Blocked by Trading Guardian",
    DEGRADED: "Saathi running with reduced capability",
  }[state] || "Saathi";
}
